    FormDataFieldEventHandler(formDataFieldStr(LedgerAllocationRule, LedgerAllocationRule, AllocationMethod), FormDataFieldEventType::Modified)]
public static void AllocationMethod_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    sender.datasource().object(fieldNum(LedgerAllocationRule, AVAFPLDestinationMainAccount)).mandatory(false);
}

